import{az as i,P as a,Q as e,aQ as r}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"面试题/项目经验/权限控制.md","filePath":"面试题/项目经验/权限控制.md","lastUpdated":1782623385000}'),t={name:"面试题/项目经验/权限控制.md"};function o(n,l,s,d,h,p){return a(),e("div",null,[...l[0]||(l[0]=[r('<h2 id="粒度划分" tabindex="-1">粒度划分 <a class="header-anchor" href="#粒度划分" aria-label="Permalink to “粒度划分”">​</a></h2><p>路由、按钮、接口 多级权限控制 动态路由</p><h2 id="鉴权流程" tabindex="-1">鉴权流程 <a class="header-anchor" href="#鉴权流程" aria-label="Permalink to “鉴权流程”">​</a></h2><ol><li>用户登录，后端返回当前用户信息，包含角色、权限列表</li><li>前端将用户信息存储在本地</li><li>依据权限数据，动态渲染路由、菜单、按钮、接口请求等</li><li>无权限时做拦截，跳转到403页面，提示用户没有权限访问</li></ol><h2 id="权限控制" tabindex="-1">权限控制 <a class="header-anchor" href="#权限控制" aria-label="Permalink to “权限控制”">​</a></h2><ol><li><p>按钮权限</p><ul><li>使用自定义指令式权限控制，定义按钮权限，把控颗粒度权限，确保用户只能访问其有权限的按钮</li><li>按钮权限，通过后台配置设定按钮权限的范围，例如隐藏按钮或禁用按钮。</li></ul></li><li><p>路由权限、</p><ul><li>静态路由，基础公共路由，不需要权限可访问，例如：登录、注册、404、403、首页、工作台</li><li>动态路由，将动态路由渲染成数据树，管理员给角色分配权限，将勾选的路由存储在后端（后端不需要定义任何格式，只做数据存储）。前端根据用户角色所分配的权限，动态渲染路由。</li><li></li><li>拦截后卫：全局路由守卫，用于拦截所有路由，判断用户是否有权限访问该路由；若无权限，则跳转到403页面，提示用户没有权限访问。</li></ul></li><li><p>菜单权限</p><ul><li>直接隐藏没有权限的菜单，做到与路由权限一致。</li></ul></li><li><p>接口权限 为每个页面定义接口权限。</p><ul><li>前端所有权限都是表层防护，可被绕过 ，需要后端做接口权限校验。</li><li>在axios请求拦截器中，添加权限校验逻辑，判断用户是否有权限访问该接口；若无权限，则返回403错误码，提示用户没有权限访问。</li><li>后端做二次校验，防止管理员修改用户权限后，前端未及时更新导致权限校验失败。</li></ul></li></ol><h2 id="权限模型" tabindex="-1">权限模型 <a class="header-anchor" href="#权限模型" aria-label="Permalink to “权限模型”">​</a></h2><ol><li>RBAC（基于角色的访问控制） <ul><li>角色：用户、管理员、超管等</li><li>权限：登录、注册、查看用户列表、查看角色列表、分配角色等</li><li>用户：每个用户都可以有多个角色，管理员为每个角色分配权限。</li><li>权限校验：在请求处理中，根据用户角色和权限，判断用户是否有权限访问该资源</li></ul></li></ol><h2 id="用户权限持久化" tabindex="-1">用户权限持久化 <a class="header-anchor" href="#用户权限持久化" aria-label="Permalink to “用户权限持久化”">​</a></h2><ol><li></li></ol><p>总结： 前端控制权限基于RBAC模型， 分为四层管控：按钮权限、路由权限、菜单权限、接口权限。前端仅做展示控制，后端做二次鉴权。</p><ol><li>通过动态路由 + 全局路由守卫控制页面访问权限。</li><li>通过权限渲染菜单</li><li>通过自定义指令控制按钮权限</li><li>在请求拦截器做接口权限拦截</li></ol>',12)])])}const u=i(t,[["render",o]]);export{m as __pageData,u as default};
